-- Sessions no longer on the club's own listing (checked against the live Bam Good Time pages on 2026-10-13).
UPDATE "Event" SET "status" = 'INACTIVE' WHERE "status" = 'ACTIVE' AND (
  ("clubId" = (SELECT id FROM Club WHERE name = 'The Bamboo Room' AND cityId = (SELECT id FROM City WHERE name = 'Vienna' AND state = 'VA')) AND substr("eventDate", 1, 10) = '2026-10-15' AND "startTime" = '12:00' AND "name" = 'Instructor-Led Guided Play')
  OR ("clubId" = (SELECT id FROM Club WHERE name = 'The Bamboo Room' AND cityId = (SELECT id FROM City WHERE name = 'Vienna' AND state = 'VA')) AND substr("eventDate", 1, 10) = '2026-10-17' AND "startTime" = '13:15')
  OR ("clubId" = (SELECT id FROM Club WHERE name = 'MJ Social' AND cityId = (SELECT id FROM City WHERE name = 'Island Park' AND state = 'NY')) AND substr("eventDate", 1, 10) IN ('2026-10-27', '2026-10-29') AND "startTime" = '16:00' AND "name" = 'Mah Jongg Open Play')
);
